B.d79=new A.q("screenBoardColumn",B.v,'Screens: board FK column (default "board").',B.f,null)
B.diT=new A.q("screenNameColumn",B.v,'Screens: name column (default "name").',B.f,null)
B.dqH=new A.q("screenDeviceColumn",B.v,'Screens: device column, "phone"/"tablet"/"web" (default "device").',B.f,null)
B.doM=new A.q("screenXColumn",B.v,'Screens: board X position column (default "x").',B.f,null)
