B.dnH=new A.q("dense",B.W,"Tighter vertical margins/paddings on rail tiles (flat and tree rows) so more rows fit per screen.",B.f,null)
B.dcH=new A.q("showProgress",B.W,'Each folder row shows a thin bar + "NN%" \u2014 DONE/TOTAL among its TASK descendants (kindColumn == fileValue) rolled up over the whole contains-subtree; notes/attachments/sub-groups are excluded. Requires statusColumn; a folder with no task descendants shows nothing.',B.f,null)
B.dm3=new A.q("breadcrumb",B.W,"Show the selected node's ancestor path above the detail (edges-mode).",B.f,null)
