B.dkL=new A.q("ownedTables",B.U,"Convertible: child tables this node OWNS via a column == the node id (e.g. {table: updates, column: nodeId}); their rows re-parent on convert.",B.f,null)
B.diz=new A.q("carryColumns",B.U,"Convertible: column names whose value travels to the new child on file\u2192folder, and back on folder\u2192file.",B.f,null)
